mapper.select:
select s.stage_id, s.competition_id, s.stage_name, s.stage_type, s.order_no, s.paper_id, p.paper_name
from competition_stage s left join paper p on s.paper_id = p.paper_id
where s.stage_id = #{stageId}

mapper.update:
update competition_stage
stage_name = #{stageName}, stage_type = #{stageType}, order_no = #{orderNo}, paper_id = #{paperId},
where stage_id = #{stageId}
